/* ============================================================
   HosVENUE — SHOW ROUND READY
   Presentation standards for every meeting & event space, so any
   room can be shown to a prospective client at a moment's notice.
   Content from Nicola Cartwright's readiness deck (Oct 2026).
   ============================================================ */
(function(){
  const SR_IMG={"floorplan":"data:image/jpeg;base64,","woodlands":"data:image/jpeg;base64,","brandon1":"data:image/jpeg;base64,","brandon2":"data:image/jpeg;base64,","wolston":"data:image/jpeg;base64,","beech":"data:image/jpeg;base64,","warwick":"data:image/jpeg;base64,","hunt":"data:image/jpeg;base64,"};
  const ROOMS=[{"k":"woodlands","name":"Woodlands Suite","style":"Cabaret · 60","items":["10 guest tables of 6, cabaret","Ironed tablecloths","Pad & pen per place setting","Water glass per setting","Whiteboard","Screen + HDMI cable","Presenter table","2 poseur tables"]},{"k":"brandon1","name":"Brandon 1 Suite","style":"Cabaret · 24","items":["4 guest tables of 6, cabaret","Ironed tablecloths","Pad & pen per place setting","Water glass per setting","Whiteboard","Screen + HDMI cable","Presenter table"]},{"k":"brandon2","name":"Brandon 2 Suite","style":"Cabaret · 12","items":["2 guest tables of 6","Ironed tablecloths","Pad & pen per place setting","Water glass per setting","Whiteboard","Tea & coffee station"]},{"k":"wolston","name":"Wolston Suite","style":"Cabaret · 36","items":["6 guest tables of 6, cabaret","Ironed tablecloths","Pad & pen per place setting","Water glass per setting","Whiteboard","Tea & coffee station at the back of room"]},{"k":"beech","name":"Beech Suite","style":"Boardroom · 16","items":["Boardroom set for 16","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable","Tea & coffee station at the back of room"]},{"k":"warwick","name":"Warwick Suite","style":"Boardroom · 10","items":["Boardroom set for 10","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable","Tea & coffee station at the back of room"]},{"k":"hunt","name":"Hunt Suite","style":"Boardroom · 14","items":["Boardroom set for 14","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable","Tea & coffee station at the back of room"]},{"k":"alkins","name":"Alkins Suite","style":"U-shape · 20","items":["U-shape for 20","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable"]},{"k":"johnson","name":"Johnson Suite","style":"Boardroom · 10","items":["Boardroom set for 10","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable"]},{"k":"jones","name":"Jones Suite","style":"Boardroom · 14","items":["Boardroom set for 14","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable","Tea & coffee station at the back of room"]},{"k":"parke","name":"Parke Suite","style":"U-shape · 16","items":["U-shape for 16 guests","Boardroom chairs","Linen-less table","Pad & pen per place setting","Water glass per setting","Whiteboard","HDMI cable","Tea & coffee station at the back of room"]}];
  const STANDARDS=[
    {h:"Purpose",t:"Every meeting and conference room at Brandon Hall Hotel & Spa is kept to a consistently high standard, ready for prospective clients to view at any time."},
    {h:"Expected standard",t:"Every room should be clean, tidy, fresh-smelling, professionally presented, fully operational and ready to impress."},
    {h:"Operationally friendly",t:"As meetings and events get busier, unless the sales & events team requests otherwise, set each room for the next event planned to be in it."},
    {h:"Standard hotel scent",t:"Brandon Hall Hotel & Spa diffusers in all meeting rooms, lobby areas and coffee areas — the signature hotel scent."}
  ];
  const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

  window.renderShowRound=function(v){
    const card=r=>{
      const img=SR_IMG[r.k];
      return `<div style="background:#fff;border:1px solid #e4e9ef;border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.05);display:flex;flex-direction:column">
        ${img?`<div style="height:170px;background:#eef1f5 url('${img}') center/cover"></div>`:`<div style="height:170px;background:linear-gradient(135deg,#1F3864,#2a4a80);display:flex;align-items:center;justify-content:center;color:#fff;font:700 16px Lato;opacity:.9">${esc(r.name)}</div>`}
        <div style="padding:14px 16px;flex:1;display:flex;flex-direction:column">
          <div style="display:flex;justify-content:space-between;align-items:baseline;gap:8px">
            <div style="font:800 16px Lato;color:#1a2b3a">${esc(r.name)}</div>
            <span style="flex:none;background:#eef2f8;color:#1F3864;font:700 11px Lato;padding:3px 9px;border-radius:999px;white-space:nowrap">${esc(r.style)}</span>
          </div>
          <div style="font:700 10.5px Lato;color:#8296a8;text-transform:uppercase;letter-spacing:.5px;margin:11px 0 6px">Set as a minimum</div>
          <ul style="margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:5px">
            ${r.items.map(it=>`<li style="display:flex;gap:8px;font-size:13px;color:#2a3645;line-height:1.4"><span style="color:#2B726A;font-weight:800;flex:none">✓</span><span>${esc(it)}</span></li>`).join('')}
          </ul>
        </div></div>`;
    };
    v.innerHTML=`
      <div style="max-width:1080px;margin:0 auto;padding:4px 2px 36px">
        <div style="background:linear-gradient(135deg,#1F3864,#2a4a80);color:#fff;border-radius:16px;padding:22px 24px;margin-bottom:16px">
          <div style="font-size:11px;letter-spacing:2px;text-transform:uppercase;opacity:.8">Brandon Hall Hotel & Spa · Meetings & Events</div>
          <div style="font-family:'Cormorant Garamond',serif;font-weight:700;font-size:30px;margin:4px 0 2px">✨ Show Round Ready</div>
          <div style="font-size:13.5px;opacity:.92;max-width:60em">Presentation standards for every venue viewing. First impressions count — any room, any time, ready to impress.</div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;margin-bottom:10px">
          ${STANDARDS.map(s=>`<div style="background:#fff;border:1px solid #e4e9ef;border-left:4px solid #b89056;border-radius:12px;padding:13px 15px">
            <div style="font:800 12px Lato;color:#1F3864;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">${esc(s.h)}</div>
            <div style="font-size:13px;color:#2a3645;line-height:1.5">${esc(s.t)}</div></div>`).join('')}
        </div>

        <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin:20px 0 10px">
          <div style="font:800 17px Lato;color:#1a2b3a">The rooms · minimum set-up</div>
          <button onclick="window.print()" style="padding:9px 15px;border:1px solid #2B726A;background:#fff;color:#2B726A;border-radius:9px;font:700 12.5px Lato;cursor:pointer">🖨 Print / Save as PDF</button>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px">
          ${ROOMS.map(card).join('')}
        </div>

        ${SR_IMG.floorplan?`<div style="margin-top:22px;background:#fff;border:1px solid #e4e9ef;border-radius:14px;padding:16px">
          <div style="font:800 15px Lato;color:#1a2b3a;margin-bottom:10px">Meeting rooms floor plan</div>
          <img src="${SR_IMG.floorplan}" alt="Floor plan" style="width:100%;max-width:900px;border-radius:10px;border:1px solid #eef1f4"></div>`:''}

        <div style="margin-top:16px;font-size:12px;color:#8296a8">Standards compiled by Nicola Cartwright · keep every space show-round ready at all times.</div>
      </div>`;
  };
})();
